import { unstable_cache } from 'next/cache';

export type Product = {
  id: string;
  sku: string;
  name: string;
  price: number;
  stock: number;
  available: boolean;
};

const PRODUCTS_TAG = 'products';

/** Simulated ERP/PIM source - updated by sync job */
let catalogSource: Product[] = [
  { id: '1', sku: 'SKU-001', name: 'Widget Pro', price: 29.99, stock: 150, available: true },
  { id: '2', sku: 'SKU-002', name: 'Gadget Plus', price: 49.99, stock: 80, available: true },
  { id: '3', sku: 'SKU-003', name: 'Tool Kit Basic', price: 19.99, stock: 0, available: false },
  { id: '4', sku: 'SKU-004', name: 'Premium Bundle', price: 99.99, stock: 25, available: true },
  { id: '5', sku: 'SKU-005', name: 'Accessory Pack', price: 14.99, stock: 200, available: true },
];

async function fetchProductsFromSource(): Promise<Product[]> {
  return [...catalogSource];
}

/** Cached product fetch - read-heavy, uses "products" tag for invalidation */
export async function getProducts(): Promise<Product[]> {
  return unstable_cache(
    fetchProductsFromSource,
    ['catalog-products'],
    { tags: [PRODUCTS_TAG], revalidate: false }
  )();
}

/** Simulates syncing thousands of SKUs from upstream ERP/PIM */
export async function syncFromUpstream(): Promise<void> {
  // Simulate network + processing delay for large catalog
  await new Promise((r) => setTimeout(r, 100));
  // In production: fetch from ERP API, transform, write to DB/cache
  catalogSource = catalogSource.map((p) => ({
    ...p,
    price: Math.round((p.price * (0.98 + Math.random() * 0.04)) * 100) / 100,
    stock: Math.max(0, p.stock + Math.floor((Math.random() - 0.3) * 20)),
    available: p.stock > 0,
  }));
}

