args.streamContent:
import { after } from 'next/server';
import { revalidateTag } from 'next/cache';
import { getProducts, syncFromUpstream } from '@/lib/products';

async function syncCatalog() {
  'use server';
  after(async () => {
    await syncFromUpstream();
    revalidateTag('products');
  });
}

export default async function AdminCatalogPage() {
  const products = await getProducts();

  return (
    <div className="min-h-screen bg-zinc-50 p-8">
      <div className="mx-auto max-w-4xl">
        <header className="mb-8 flex flex-wrap items-center justify-between gap-4">
          <h1 className="text-2xl font-semibold text-zinc-900">
            Product Catalog
          </h1>
          <form action={syncCatalog}>
            <button
              type="submit"
              className="rounded-lg bg-zinc-900 px-4 py-2 text-sm font-medium text-white transition hover:bg-zinc-800 focus:outline-none focus:ring-2 focus:ring-zinc-500 focus:ring-offset-2"
            >
              Sync latest catalog
            </button>
          </form>
        </header>

        <p className="mb-6 text-sm text-zinc-500">
          Trigger a sync when upstream ERP/PIM data changes. The catalog
          refreshes in the background and updates across all views shortly after.
        </p>

        <div className="overflow-hidden rounded-lg border border-zinc-200 bg-white shadow-sm">
          <table className="min-w-full divide-y divide-zinc-200">
            <thead>
              <tr>
                <th className="px-6 py-3 text-left text-xs font-medium uppercase tracking-wider text-zinc-500">
                  SKU
                </th>
                <th className="px-6 py-3 text-left text-xs font-medium uppercase tracking-wider text-zinc-500">
                  Name
                </th>
                <th className="px-6 py-3 text-right text-xs font-medium uppercase tracking-wider text-zinc-500">
                  Price
                </th>
                <th className="px-6 py-3 text-right text-xs font-medium uppercase tracking-wider text-zinc-500">
                  Stock
                </th>
                <th className="px-6 py-3 text-center text-xs font-medium uppercase tracking-wider text-zinc-500">
                  Available
                </th>
              </tr>
            </thead>
            <tbody className="divide-y divide-zinc-200">
              {products.map((product) => (
                <tr key={product.id} className="hover:bg-zinc-50">
                  <td className="whitespace-nowrap px-6 py-4 text-sm font-mono text-zinc-900">
                    {product.sku}
                  </td>
                  <td className="px-6 py-4 text-sm text-zinc-900">
                    {product.name}
                  </td>
                  <td className="whitespace-nowrap px-6 py-4 text-right text-sm text-zinc-900">
                    ${product.price.toFixed(2)}
                  </td>
                  <td className="whitespace-nowrap px-6 py-4 text-right text-sm text-zinc-900">
                    {product.stock}
                  </td>
                  <td className="px-6 py-4 text-center">
                    <span
                      className={`inline-flex rounded-full px-2 py-0.5 text-xs font-medium ${
                        product.available
                          ? 'bg-emerald-100 text-emerald-800'
                          : 'bg-zinc-100 text-zinc-600'
                      }`}
                    >
                      {product.available ? 'Yes' : 'No'}
                    </span>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}

